SELECT

FROM cust_lead
WHERE is_latest = 1
  AND deleted = 0

    AND (cust_name LIKE CONCAT('%', #{keyword}, '%')
         OR unified_credit_code LIKE CONCAT('%', #{keyword}, '%'))


    AND lead_status = #{status}


    AND owner_org_id = #{ownerOrgId}

ORDER BY created_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM cust_lead WHERE is_latest = 1 AND deleted = 0
AND (cust_name LIKE CONCAT('%', #{keyword}, '%') OR unified_credit_code LIKE CONCAT('%', #{keyword}, '%'))
AND lead_status = #{status}
AND owner_org_id = #{ownerOrgId}

SELECT COUNT(*) FROM cust_lead
WHERE deleted = 0
  AND cust_name = #{custName}
  AND lead_status IN ('PENDING_APPROVAL', 'APPROVED')

    AND id != #{excludeLeadId}
